/**
 * useAppPolicy Hook
 *
 * 범용 Policy Hook - 모든 Entity의 CRUD 정책을 한 번에 제공
 * 여러 Entity 정책을 동시에 체크해야 할 때 사용
 */

import { useMemo } from 'react';
import { useDisplayNetworkStatus } from '@/shared/store/network';
import { useGetTripActivation } from '@/entities/trip/data/useGetTripActivation';
import { TRIP_POLICIES, SCHEDULE_POLICIES, EXPENSE_POLICIES, SERVICE_POLICIES } from './constants';
import type { CRUDPermission, ServiceConfig, PolicyKey, ActivationStatus } from './types';

/**
 * App Policy Context
 *
 * 모든 Entity의 CRUD 정책 + Service 설정
 */
export interface AppPolicyContext {
  trip: {
    create: CRUDPermission;
    read: CRUDPermission;
    update: CRUDPermission;
    delete: CRUDPermission;
  };
  schedule: {
    create: CRUDPermission;
    read: CRUDPermission;
    update: CRUDPermission;
    delete: CRUDPermission;
  };
  expense: {
    create: CRUDPermission;
    read: CRUDPermission;
    update: CRUDPermission;
    delete: CRUDPermission;
  };
  service: ServiceConfig;
}

/**
 * 앱 전역 Policy Hook
 *
 * @param tripId - Trip ID (optional)
 * @returns 모든 Entity의 CRUD 정책
 *
 * @example
 * ```tsx
 * // 여러 Entity 정책을 동시에 체크
 * const policy = useAppPolicy(tripId);
 *
 * if (!policy.schedule.create.allowed) {
 *   return <DisabledMessage reason={policy.schedule.create.reason} />;
 * }
 *
 * if (policy.expense.create.mode === 'manual-only') {
 *   return <ManualInputForm />;
 * }
 *
 * // Service 설정도 접근 가능
 * if (policy.service.mapProvider === 'mapbox') {
 *   return <OfflineMap />;
 * }
 * ```
 */
export function useAppPolicy(tripId?: string): AppPolicyContext {
  const networkStatus = useDisplayNetworkStatus();

  const { data: activation } = useGetTripActivation(tripId ?? '');

  const isActivated = activation?.isActivated ?? false;
  const activationStatus: ActivationStatus = tripId && isActivated ? 'active' : 'inactive';

  // unknown도 Remote 기능을 열지 않는다. 현재 4-state 권한 표의 제한 모드를 재사용한다.
  const policyNetworkStatus = networkStatus === 'online' ? 'online' : 'offline';
  const policyKey: PolicyKey = `${policyNetworkStatus}_${activationStatus}`;

  return useMemo(
    () => ({
      trip: {
        create: TRIP_POLICIES.create[policyKey],
        read: TRIP_POLICIES.read[policyKey],
        update: TRIP_POLICIES.update[policyKey],
        delete: TRIP_POLICIES.delete[policyKey],
      },
      schedule: {
        create: SCHEDULE_POLICIES.create[policyKey],
        read: SCHEDULE_POLICIES.read[policyKey],
        update: SCHEDULE_POLICIES.update[policyKey],
        delete: SCHEDULE_POLICIES.delete[policyKey],
      },
      expense: {
        create: EXPENSE_POLICIES.create[policyKey],
        read: EXPENSE_POLICIES.read[policyKey],
        update: EXPENSE_POLICIES.update[policyKey],
        delete: EXPENSE_POLICIES.delete[policyKey],
      },
      service: SERVICE_POLICIES[policyKey],
    }),
    [policyKey],
  );
}
/**
 * Policy Layer Types (CRUD-Centric)
 *
 * 동작 중심 구조로 4-state policy matrix 정의
 * - online_active: 온라인 + 활성화 (전체 기능)
 * - online_inactive: 온라인 + 비활성 (서버 직접 접근)
 * - offline_active: 오프라인 + 활성화 (수동 입력 모드)
 * - offline_inactive: 오프라인 + 비활성 (읽기 전용)
 */

import type { NetworkStatus } from '@/shared/store/network';

export type { NetworkStatus } from '@/shared/store/network';
export type ActivationStatus = 'active' | 'inactive';

// 실제 관측은 세 상태이며, 기존 권한 표는 unknown의 제한 모드를 offline과 공유한다.
export type PolicyKey = `${Exclude<NetworkStatus, 'unknown'>}_${ActivationStatus}`;

/**
 * CRUD Operation Mode
 *
 * - full: 전체 기능 사용 가능
 * - manual-only: 수동 입력만 가능 (API 호출 없이 텍스트만)
 * - limited: 일부 필드만 수정 가능
 */
export type CRUDMode = 'full' | 'manual-only' | 'limited';

/**
 * CRUD Permission
 */
export interface CRUDPermission {
  allowed: boolean;
  mode?: CRUDMode;
  reason?: string; // 비활성화된 경우 사용자에게 보여줄 이유

  // 필드별 검증 규칙 (optional)
  validation?: {
    required?: string[]; // 필수 필드
    optional?: string[]; // 선택 필드
    allowed?: string[]; // 허용된 필드 (limited mode)
    blocked?: string[]; // 차단된 필드 (limited mode)
    enforced?: Record<string, unknown>; // 강제 값 (e.g., latitude: null)
  };
}

/**
 * CRUD Operation Policies
 *
 * 각 CRUD 동작이 4가지 상태에서 어떻게 동작하는지 정의
 */
export interface CRUDOperationPolicies {
  create: Record<PolicyKey, CRUDPermission>;
  read: Record<PolicyKey, CRUDPermission>;
  update: Record<PolicyKey, CRUDPermission>;
  delete: Record<PolicyKey, CRUDPermission>;
}

export type TripPolicies = CRUDOperationPolicies;
export type SchedulePolicies = CRUDOperationPolicies;
export type ExpensePolicies = CRUDOperationPolicies;

/**
 * Service Layer Configuration
 *
 * 서비스 레이어는 상태별 설정 (기존 구조 유지)
 */
export interface ServiceConfig {
  mapProvider: 'google' | 'mapbox' | 'none';
  searchMode: 'api' | 'cache' | 'disabled';
  syncStrategy: 'immediate' | 'background' | 'manual' | 'disabled';
  uiMode: 'full' | 'limited' | 'readonly';
}

/**
 * Service Layer Policies
 */
export type ServicePolicies = Record<PolicyKey, ServiceConfig>;
import React, { createContext, useContext, useEffect, useRef, useState, useCallback } from 'react';
import { networkStore, useRealNetworkStatus, type NetworkStatus } from '@/shared/store/network';
import { syncData } from './engine';

/**
 * SyncProvider Context
 *
 * 동기화 상태와 수동 트리거 제공
 */
interface SyncContextValue {
  isSyncing: boolean;
  lastSyncedAt: Date | null;
  triggerManualSync: () => Promise<void>;
}

const SyncContext = createContext<SyncContextValue | undefined>(undefined);

/**
 * useSyncContext Hook
 *
 * 컴포넌트에서 동기화 상태와 수동 트리거 접근
 *
 * @example
 * ```tsx
 * const { isSyncing, triggerManualSync } = useSyncContext();
 * ```
 */
export function useSyncContext() {
  const context = useContext(SyncContext);
  if (!context) {
    throw new Error('useSyncContext must be used within SyncProvider');
  }
  return context;
}

/**
 * 동기화 Provider
 *
 * 앱 전체를 감싸서 자동 동기화 기능 제공 (Push + Pull)
 * - 네트워크 상태 감지
 * - 오프라인 → 온라인 전환 시 자동 동기화
 * - 앱 시작 시 한 번 동기화
 * - 주기적 동기화 (선택적)
 * - 디버그 모드: 강제 온라인/오프라인 설정 가능
 *
 * @example
 * ```tsx
 * <SyncProvider enablePeriodicSync={false}>
 *   <App />
 * </SyncProvider>
 * ```
 */
interface SyncProviderProps {
  children: React.ReactNode;
  enablePeriodicSync?: boolean; // 주기적 동기화 활성화 (기본: false)
  syncInterval?: number; // 주기적 동기화 간격 (ms, 기본: 5분)
}

export function SyncProvider({
  children,
  enablePeriodicSync = false,
  syncInterval = 5 * 60 * 1000, // 5분
}: SyncProviderProps) {
  const networkStatus = useRealNetworkStatus();

  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);
  // null은 첫 effect 미처리이며, 실제 네트워크의 unknown과 구분한다.
  const previousStatusRef = useRef<NetworkStatus | null>(null);

  /**
   * 동기화 실행 함수 (중복 실행 방지)
   */
  const executeSync = useCallback(
    async (reason: string) => {
      if (networkStore.realStatus !== 'online' || networkStore.override !== null) {
        return;
      }

      if (isSyncing) {
        console.log('⏭️ [SyncProvider] Sync already in progress, skipping...');
        return;
      }

      try {
        setIsSyncing(true);
        console.log(`🔄 [SyncProvider] Sync triggered: ${reason}`);

        await syncData(); // Push + Pull

        const now = new Date();
        setLastSyncedAt(now);

        console.log(`✅ [SyncProvider] Sync completed: ${reason}`, {
          lastSyncedAt: now.toISOString(),
        });
      } catch (error) {
        console.error(`❌ [SyncProvider] Sync failed: ${reason}`, error);
      } finally {
        setIsSyncing(false);
      }
    },
    [isSyncing],
  );

  /**
   * 수동 동기화 트리거 (UI에서 호출)
   */
  const triggerManualSync = useCallback(async () => {
    await executeSync('Manual trigger');
  }, [executeSync]);

  /**
   * 최초 online과 이후 online 전환마다 한 번 동기화
   */
  useEffect(() => {
    const previousStatus = previousStatusRef.current;
    previousStatusRef.current = networkStatus;

    // 최초 unknown 확정과 오프라인 복구 모두 실제 online에서 시작한다.
    if (previousStatus !== 'online' && networkStatus === 'online') {
      if (previousStatus === null) {
        console.log('🚀 [SyncProvider] Initial sync on app start');
        executeSync('App startup');
      } else {
        console.log('🌐 [SyncProvider] Network recovered → Starting sync');
        executeSync('Network recovery');
      }
    }

    // 온라인 → 오프라인 전환 로그
    if (previousStatus === 'online' && networkStatus === 'offline') {
      console.log('📴 [SyncProvider] Network offline → Sync paused');
    }
  }, [networkStatus, executeSync]);

  /**
   * 주기적 동기화 (선택적)
   */
  useEffect(() => {
    if (!enablePeriodicSync) {
      return;
    }

    console.log(`⏰ [SyncProvider] Periodic sync enabled (${syncInterval / 1000}s interval)`);

    const intervalId = setInterval(() => {
      if (networkStatus === 'online') {
        executeSync('Periodic sync');
      } else {
        console.log('⏭️ [SyncProvider] Skipping periodic sync (offline)');
      }
    }, syncInterval);

    return () => clearInterval(intervalId);
  }, [enablePeriodicSync, syncInterval, networkStatus, executeSync]);

  /**
   * Context Value
   */
  const value: SyncContextValue = {
    isSyncing,
    lastSyncedAt,
    triggerManualSync,
  };

  return <SyncContext.Provider value={value}>{children}</SyncContext.Provider>;
}
