  onPress?: () => void;
  onMenuPress?: (event: any) => void;
}

export function ScheduleCard({
  date,
  time,
  title,
  location,
  latitude,
  expense,
  expenseCount,
  currency = 'USD',
  className,
  onPress,
  onMenuPress,
}: ScheduleCardProps) {
